def _processar_cerebro_local(comando: str) -> bool:
    """CEREBRO LOCAL: tenta resolver o comando por REGRA (sem nuvem). Retorna
    True se tratou (imprimiu a saida); False se nao entendeu."""
    cmd = comando.lower().strip()
    n = _norm_pt(cmd)
    if not n:
        return False

    # MENU DE AJUDA: mostra tudo (como ligar IA local/nuvem e exemplos).
    if n in ("ajuda", "menu", "comandos", "help", "opcoes", "oqueeufaco",
             "comouso", "comoeuuso", "comousoagente", "comousar", "comoeuvouso",
             "ajudame", "meajuda", "precisodeajuda", "oquesabe",
             "ial", "opcoesdoagente", "listadecomandos", "manual", "oquepossofazer",
             "quaiscomandos", "mostramenu", "verajuda", "socorro"):
        _menu_ajuda_local()
        return True

    # guarda o ultimo pedido pra permitir "de novo" (sem guardar o proprio
    # "de novo", senao entraria em loop)
    if n not in ("denovo", "repete", "repeteisso", "outravez", "repetir"):
        _ULTIMO_COMANDO["texto"] = comando

    def _rel(r):
        r = str(r).strip()
        print(f"\n[Local]: {r}")
        try:
            falar(r[:200])
        except Exception:
            pass
        historico_conversas.append({"role": "assistant", "content": r})
        try:
            salvar_historico()
        except Exception:
            pass

    # ---- Interruptor da nuvem (funciona sempre, ate com a nuvem desligada) ----
    if _r20_grupo_comando(comando) == 'nuvem_on' or n in ("ligaria", "ligarai", "ligarias", "ligarais", "ligarnuvem",
             "nuvemligada", "usaria", "ligaia", "ligaias", "ligarmodoia"):
        config["usar_ia_nuvem"] = True
        salvar_json(ARQ_CONFIG, config)
        print("\n[Nuvem]: IAs da nuvem LIGADAS. Agora eu uso o rodizio (Groq, GitHub etc.)")
        print("        para conversa e tarefas que o cerebro local nao faz por regra.")
        print("        Quando as cotas apertarem, digite 'desligar ia' para voltar ao")
        print("        modo 100% local (sem limite).")
        return True
    if _r20_grupo_comando(comando) == 'nuvem_off' or n in ("desligaria", "desligarai", "desligarias", "desligarais",
             "desligarnuvem", "nuvemdesligada", "somentelocal",
             "desligaia", "desligaias", "modolocal"):
        config["usar_ia_nuvem"] = False
        salvar_json(ARQ_CONFIG, config)
        print("\n[Nuvem]: IAs da nuvem DESLIGADAS. Agora eu rodo 100% LOCAL: sem API,")
        print("        sem cota e sem limite, instantaneo e offline. As acoes que eu")
        print("        conheco por regra continuam funcionando; para conversa solta,")
        print("        digite 'ligar ia' quando quiser voltar a usar a nuvem.")
        return True
    # IA NEURAL LOCAL (llama.cpp): prepara/liga/desliga/consulta.
    if _r20_grupo_comando(comando) == 'preparar' or n in ("criaria", "criai", "fazeria", "iniciaria", "iniciaria",
             "baixaria", "instalaria", "ligariaoffline", "ativarialogo",
             "motorlocal", "prepararia", "ligarialogo", "ligariadepc"):
        preparar_ia_local(); return True
    if _r20_grupo_comando(comando) == 'status' or n in ("statusia", "statusial", "statusdalial", "ialpronta", "comoestaria",
             "estadoial", "estadoia", "ialocalpronta", "prontaal", "comovaial", "iadepronta"):
        print("\n[IA Local]: " + ("PRONTA e respondendo offline (sem cota)."
              if ia_local_disponivel() else "indisponivel agora (pode estar parado ou iniciando). Use criar ia para preparar/iniciar; se faltarem arquivos, pode haver download."))
        return True
    if _r20_grupo_comando(comando) == 'parar' or n in ("desligarialocal", "pararia", "mataria", "encerraria",
             "desligarial", "pararialogo"):
        print('\n[IA Local]: ' + _r20_encerrar_motor())
        return True

    # Ajuda dos modos nao deve abrir o seletor de ferramentas nem mudar
    # configuracoes implicitamente: uma pergunta nao e uma autorizacao.
    if n in ("ianuvem", "ialocal") or (
            _eh_pergunta_de_conversa(comando)
            and any(x in n for x in ("ialocal", "ianuvem", "iadanuvem"))):
        _rel("A IA local conversa no seu PC usando o modelo instalado, sem chave "
             "de API externa nem cobranca por chamada. A nuvem usa provedores "
             "online e suas cotas. Para VOLTAR ao modo local, digite: desligar ia. "
             "Para USAR a nuvem, digite: ligar ia. Para conferir o motor local, "
             "digite: status ia. 'desligar ia local' encerra o motor local; "
             "nao e o comando para voltar ao modo local.")
        return True

    # Prioridade de intencao: a palavra "armazenamento" numa explicacao
    # nao autoriza consultar discos; "firewall" nao autoriza muda-lo.
    if _pedido_explicativo(comando):
        return False  # processar_atalho_rapido encaminha ao chat local/nuvem

    # ---- Conversa / saudações (resposta local, sem nuvem) ----
    saud = ("ola", "oi", "oie", "ei", "iae", "eai", "eae", "eaew",
            "salve", "falae", "fala", "hey", "hello", "hola", "bomdia", "boatarde",
            "boanoite", "tudobem", "tudobom", "comovai", "deboa",
            "blz", "beleza", "tranquilo", "firmeza")
    if n in saud or n.startswith(("ola", "oie", "bomdia", "boatarde", "boanoite", "eai", "iae")):
        _nome = ""
        try:
            _c = ler_memoria_core() if "ler_memoria_core" in globals() else ""
            if _c and "Guilherme" in (_c or ""):
                _nome = ", Guilherme"
        except Exception:
            _nome = ""
        _rel(f"Oi{_nome}! Estou no modo local (sem limite). Mande uma acao, por "
             "exemplo 'abre o youtube', 'otimiza tudo', 'qual a versao do windows' "
             "ou 'organiza minha pasta de downloads'.")
        return True
    if ("oquevocefaz" in n or "quevocefaz" in n or "oquevoce" in n
            or n in ("oquesuasfuncoes", "funcoes", "oquepossofazer", "quervoce")):
        _rel(_INTRO_LOCAL)
        return True
    if n.startswith(("obrigad", "valeu", "vlw")) or n in ("obrigado", "obrigada", "valeu"):
        _rel("De nada! Estou aqui no modo local. Precisa de mais alguma coisa?")
        return True
    if n.startswith(("tchau", "atelogo", "flw")) or n in ("tchau", "flw"):
        _rel("Falou! Vou ficar por aqui. E so chamar quando precisar.")
        return True

