def _baixar_com_progresso(url: str, destino: str, rotulo: str):
    """Baixa um arquivo mostrando progresso no console (urllib puro, sem pip)."""
    import urllib.request
    os.makedirs(os.path.dirname(destino), exist_ok=True)
    req = urllib.request.Request(url, headers={"User-Agent": "SuperAgentePC"})
    with urllib.request.urlopen(req, timeout=60) as r:
        total = 0
        try:
            total = int(r.headers.get("Content-Length") or 0)
        except Exception:
            total = 0
        baixado = 0
        tmp = destino + ".part"
        with open(tmp, "wb") as f:
            while True:
                pedaco = r.read(1024 * 256)
                if not pedaco:
                    break
                f.write(pedaco)
                baixado += len(pedaco)
                if total:
                    pct = min(100, baixado * 100 // total)
                    mb = baixado // (1024 * 1024)
                    tmb = total // (1024 * 1024)
                    print(f"\r        {rotulo}: {pct:3d}% ({mb}/{tmb} MB)", end="", flush=True)
        print()
    os.replace(tmp, destino)


def _acha_llama_server() -> str:
    """Procura llama-server.exe na pasta da IA local (apos extrair o zip)."""
    for raiz, _dirs, arqs in os.walk(_PASTA_IA_LOCAL):
        for a in arqs:
            if a.lower() == "llama-server.exe":
                return os.path.join(raiz, a)
    return ""


def _baixar_motor_llama() -> str:
    """Baixa e extrai o binario do llama.cpp para Windows x64 (CPU). Devolve o
    caminho do llama-server.exe. Procura o build 'win-cpu-x64' nas releases
    recentes (a 'latest' hoje so aponta para nightly e nao traz os binarios);
    se nao achar, usa uma build conhecida como reserva."""
    import zipfile
    import urllib.request
    os.makedirs(_PASTA_IA_LOCAL, exist_ok=True)
    ja = _acha_llama_server()
    if ja:
        return ja

    def _baixar_e_extrair(url_zip):
        if not url_zip:
            return ""
        destino_zip = os.path.join(_PASTA_IA_LOCAL, "llama_win.zip")
        _baixar_com_progresso(url_zip, destino_zip, "Motor llama.cpp")
        with zipfile.ZipFile(destino_zip) as z:
            z.extractall(_PASTA_IA_LOCAL)
        try:
            os.remove(destino_zip)
        except Exception:
            pass
        return _acha_llama_server()

    def _escolhe_asset(assets):
        # Procura EXATAMENTE o build de CPU x64 (ex.: llama-b10830-bin-win-cpu-x64.zip).
        for ativo in assets:
            nome = (ativo.get("name") or "").lower()
            if nome.endswith("win-cpu-x64.zip"):
                return ativo.get("browser_download_url")
        # Reforco: win + x64 + .zip sem gpu/arm.
        for ativo in assets:
            nome = (ativo.get("name") or "").lower()
            if ("win" in nome and "x64" in nome and nome.endswith(".zip")
                    and not any(k in nome for k in
                                ("cuda", "vulkan", "rocm", "sycl", "hip", "opencl",
                                 "openvino", "arm64", "cudart"))):
                return ativo.get("browser_download_url")
        return None

    # 1) Varre as releases recentes procurando o build de CPU x64.
    try:
        req = urllib.request.Request(
            "https://api.github.com/repos/ggml-org/llama.cpp/releases?per_page=30",
            headers={"User-Agent": "SuperAgentePC", "Accept": "application/vnd.github+json"})
        with urllib.request.urlopen(req, timeout=45) as r:
            releases = json.loads(r.read().decode("utf-8", "ignore"))
        for rel in releases:
            url_zip = _escolhe_asset(rel.get("assets", []))
            if url_zip:
                srv = _baixar_e_extrair(url_zip)
                if srv:
                    return srv
                break
    except Exception as e:
        print(f"        (GitHub API nao respondeu: {type(e).__name__}; tentando link reserva)")

    # 2) Reserva: build estavel conhecido do llama.cpp (CPU win-x64).
    for reserva in (
        "https://github.com/ggml-org/llama.cpp/releases/download/b10830/llama-b10830-bin-win-cpu-x64.zip",
    ):
        try:
            srv = _baixar_e_extrair(reserva)
            if srv:
                return srv
        except Exception:
            continue
    return ""


def _iniciar_servidor_ia_local(caminho_modelo: str) -> bool:
    """Inicia somente o GGUF indicado, com prazo monotônico e processo rastreado."""
    import time
    global _proc_ia_local
    srv = _acha_llama_server()
    if not srv:
        _r20_estado('falhou', 'Executavel ausente'); return False
    if not _lock_ia_local.acquire(timeout=2):
        print('[IA Local]: inicializacao ja em andamento.'); return False
    try:
        if _r20_servidor_confere(caminho_modelo):
            print('[IA Local]: motor ja disponivel; nao reiniciei.'); return True
        if _proc_ia_local is not None and _proc_ia_local.poll() is None:
            print('[IA Local]: processo existente ainda nao esta pronto; nao iniciei outro.'); return False
        # Um servico HTTP desconhecido na porta nao deve ser reaproveitado.
        try:
            _r20_http_json('/health', 1)
        except Exception:
            pass
        else:
            _r20_estado('falhou', 'Porta responde com identidade incompatível.')
            print('[IA Local]: servidor na porta nao corresponde ao GGUF esperado; nao substitui nada.'); return False
        _r20_estado('iniciando', 'Carregando GGUF existente')
        cmd = [srv, '-m', caminho_modelo, '--port', str(_PORTA_IA_LOCAL), '--host', '127.0.0.1',
               '-t', str(_r20_opcoes()['threads']), '--ctx-size', '4096']
        with open(os.path.join(_PASTA_IA_LOCAL, 'servidor.log'), 'a', encoding='utf-8', errors='ignore') as log:
            _proc_ia_local = subprocess.Popen(cmd, stdout=log, stderr=log,
                                             creationflags=getattr(subprocess, 'CREATE_NO_WINDOW', 0))
        globals()['_caminho_modelo_local'] = caminho_modelo
        prazo = time.monotonic() + 90
        while time.monotonic() < prazo:
            if _proc_ia_local.poll() is not None:
                _r20_estado('falhou', 'Processo saiu durante inicializacao'); return False
            if _r20_servidor_confere(caminho_modelo, prazo):
                return True
            time.sleep(max(0, min(0.5, prazo-time.monotonic())))
        _r20_estado('falhou', 'Prazo de inicializacao excedido; processo mantido para diagnostico')
        return False
    except Exception as erro:
        _r20_estado('falhou', type(erro).__name__)
        return False
    finally:
        _lock_ia_local.release()


def _acha_modelo_gguf() -> str:
    """Devolve o caminho de um modelo .gguf ja baixado (qualquer tamanho) ou ''."""
    try:
        if os.path.isdir(_PASTA_IA_LOCAL):
            for _raiz, _d, _arqs in os.walk(_PASTA_IA_LOCAL):
                for _a in _arqs:
                    if _a.lower().endswith(".gguf"):
                        _cam = os.path.join(_raiz, _a)
                        try:
                            if os.path.getsize(_cam) > 100_000_000:
                                return _cam
                        except Exception:
                            pass
    except Exception:
        pass
    return ""


def _auto_subir_ia_local() -> None:
    """Sobe o servidor da IA local (se motor+modelo ja existirem) SEM baixar
    nada e sem travar a abertura - usado na inicializacao automatica."""
    try:
        if ia_local_disponivel():
            return
        gguf = _acha_modelo_gguf()
        if not gguf or not _acha_llama_server():
            return
        if _iniciar_servidor_ia_local(gguf):
            print(" IA neural local ligada (offline, sem cota nem limite).")
    except Exception:
        pass


def preparar_ia_local() -> bool:
    """Garante motor + modelo baixados e o servidor no ar. Mostra progresso.
    Retorna True se a IA neural local esta pronta para conversar."""
    global _modelo_ia_local
    if ia_local_disponivel():
        print('[IA Local]: motor ja disponivel; nao reiniciei nem baixei arquivos.')
        return True
    os.makedirs(_PASTA_IA_LOCAL, exist_ok=True)
    print("\n[IA Local]: preparando a IA neural offline (motor llama.cpp + modelo).")
    print("           Download UNICO - depois roda sem internet, de graca e sem limite.")
    try:
        srv = _baixar_motor_llama()
        if not srv:
            print("[IA Local]: nao consegui baixar o motor (sem internet ou GitHub fora do ar).")
            print("           Tente de novo mais tarde com internet; as acoes locais continuam.")
            return False
        _gguf_existente = _acha_modelo_gguf()
        if _gguf_existente:
            caminho_modelo = _gguf_existente
            rotulo = os.path.basename(_gguf_existente)
        else:
            arq_modelo, urls_modelo, rotulo = _escolher_modelo_local()
            caminho_modelo = os.path.join(_PASTA_IA_LOCAL, arq_modelo)
        if not os.path.exists(caminho_modelo) or os.path.getsize(caminho_modelo) < 100_000_000:
            print(f"[IA Local]: baixando o modelo {rotulo} (pode levar alguns minutos na 1a vez)...")
            _baixou = False
            urls_modelo = urls_modelo if not _gguf_existente else []
            for _u in urls_modelo:
                try:
                    _baixar_com_progresso(_u, caminho_modelo, "Modelo")
                    if os.path.exists(caminho_modelo) and os.path.getsize(caminho_modelo) > 100_000_000:
                        _baixou = True
                        break
                except Exception as _em:
                    print(f"        (esse link falhou: {type(_em).__name__}; tentando outro espelho)")
            if not _baixou:
                print("[IA Local]: nao consegui baixar o modelo (sem internet ou links fora do ar).")
                print("           Tente de novo mais tarde; as acoes por regra continuam funcionando.")
                return False
        print("[IA Local]: iniciando o motor local (na 1a vez leva alguns segundos)...")
        if _iniciar_servidor_ia_local(caminho_modelo):
            _modelo_ia_local = os.path.basename(caminho_modelo)
            print("[IA Local]: PRONTA! IA neural offline ativa - sem cota e sem limite.")
            return True
        print("[IA Local]: o motor baixou mas nao subiu. Veja ia_local/servidor.log.")
        return False
    except Exception as e:
        print(f"[IA Local]: falha ao preparar ({type(e).__name__}: {e}). Acoes locais seguem funcionando.")
        return False


def ia_local_disponivel() -> bool:
    disponivel = _r20_servidor_confere()
    if not disponivel and _r20_estado()['estado'] not in ('iniciando','ocupado','falhou'):
        _r20_estado('parado', 'Motor indisponivel ou identidade nao confirmada')
    return disponivel


_cache_contexto_pc = None

def _contexto_pc() -> str:
    """Resumo enxuto do PC (so leitura) para a IA neural saber quem/como o
    sistema e, sem precisar adivinhar. Cacheado (nao muda numa sessao)."""
    global _cache_contexto_pc
    if _cache_contexto_pc is not None:
        return _cache_contexto_pc
    import platform as _pl
    fatos = []
    try:
        fatos.append(f"Sistema: {_pl.system()} {_pl.release()} (build {_pl.version()})")
        fatos.append(f"PC: {_pl.node()}")
        fatos.append(f"Nivel configurado do agente: {config.get('nivel_permissao','padrao')}; elevacao do Windows nao verificada neste resumo")
    except Exception:
        pass
    try:
        import psutil
        ram = psutil.virtual_memory()
        fatos.append(f"RAM total: {ram.total//(1024**3)}GB ({100-ram.percent:.0f}% livre agora)")
        fatos.append(f"CPU: {psutil.cpu_count(logical=True)} nucleos")
    except Exception:
        pass
    _cache_contexto_pc = " | ".join(fatos)
    return _cache_contexto_pc


# ================= IDENTIDADE / PODERES (resposta por REGRA, nunca inventada) =================
# A IA neural e pequena e, por treino, costuma dizer que e "assistente de voz"
# e que "nao tem acesso ao sistema". Isso e MENTIRA neste agente: ele roda como
# ADMINISTRADOR e executa de verdade. Entao perguntas sobre admin/poderes/quem
# e voce sao respondidas por REGRA (determinista), sem passar pela neural.

def _resposta_identidade() -> str:
    """Distingue configuracao do agente de elevacao real no Windows."""
    nivel = config.get("nivel_permissao", "padrao")
    estado = "Nao confirmei a elevacao do processo Windows."
    if os.name == "nt":
        try:
            import ctypes
            elevado = bool(ctypes.windll.shell32.IsUserAnAdmin())
            estado = ("O processo esta elevado como administrador no Windows." if elevado
                      else "O processo NAO esta elevado como administrador no Windows.")
        except Exception:
            pass
    confirmacoes = ("No modo admin, varias ferramentas dispensam confirmacao; "
                    "nao e correto prometer sim/nao em toda mudanca." if nivel == "admin"
                    else "As confirmacoes dependem da ferramenta e do nivel configurado.")
    return (f"{estado} Nivel configurado no agente: {nivel}. {confirmacoes} "
            f"Tenho {len(tools)} ferramentas registradas, mas cada acao depende "
            "do programa instalado, das permissoes e do resultado real da execucao.")


